{"code": "import numpy as np
from collections import deque

BOX = "SPY"   # sky-blue, pink and yellow boxes; the glyph inside each is black

def shape_key(rows):
    # the 5x5 black glyph, read the same way whatever its turn: the smallest of its four rotations
    m = np.array([[ch == "B" for ch in row] for row in rows])
    return min("/".join("".join("#" if v else "." for v in row) for row in np.rot90(m, k)) for k in range(4))

def read_chains(board):
    # a chain is a row of 7x7 boxes side by side; find it by its top edge: a run of one box colour, 7k long,
    # with another colour above it and the same run 6 rows below
    chains = []
    for r in range(58):
        c = 0
        while c < 64:
            col = board[r][c]
            if col not in BOX or (r and board[r - 1][c] == col):
                c += 1
                continue
            e = c
            while e < 64 and board[r][e] == col:
                e += 1
            if (e - c) % 7 == 0 and board[r + 6][c:e] == col * (e - c):
                n = (e - c) // 7
                glyphs = [shape_key([board[r + 1 + a][c + 1 + 7 * i:c + 6 + 7 * i] for a in range(5)]) for i in range(n)]
                chains.append({"r": r, "c": c, "n": n, "colour": col, "glyphs": glyphs, "top": board[r][0] == "g"})
            c = e
    return chains

def read_level(board):
    chains = read_chains(board)
    top = sorted((ch for ch in chains if ch["top"]), key=lambda ch: (ch["r"], ch["c"]))
    rules = []
    for a, b in zip(top, top[1:]):
        end = a["c"] + 7 * a["n"]
        if a["r"] == b["r"] and b["c"] == end + 3 and board[a["r"] + 3][end:b["c"]] == "GGG":
            rules.append((a, b))
    bottom = sorted((ch for ch in chains if not ch["top"]), key=lambda ch: ch["r"])
    src, ans = bottom[0], bottom[1]
    # the white bracket: its top row is 3 rows above the box it marks, starting one column in
    wr = min(r for r in range(64) if "W" in board[r])
    wc = board[wr].index("W")
    sel = None
    for ch in [ans] + [x for rule in rules for x in rule]:
        if ch["r"] - 3 == wr and (wc - ch["c"] - 1) % 7 == 0 and 0 <= (wc - ch["c"] - 1) // 7 < ch["n"]:
            sel = (ch, (wc - ch["c"] - 1) // 7)
    return {"rules": rules, "src": src, "ans": ans, "sel": sel}

names = {}
def nm(g):
    # short names for printing: g0, g1, ... in the order glyphs are first seen
    return names.setdefault(g, f"g{len(names)}")

