{"code": "NEXT, PREV = {}, {}   # what one press of 2 (down) does to a glyph; 1 (up) is the reverse

def learn(before, after, move):
    if before == after:
        return
    a, b = (before, after) if move == "2" else (after, before)
    NEXT[a], PREV[b] = b, a

def known_path(a, b, limit=6):
    # shortest known way from glyph a to glyph b: k presses of 2 or of 1; None when that part of the cycle is unknown
    best = None
    for move, table in (("2", NEXT), ("1", PREV)):
        x, k = a, 0
        while x != b and x in table and k < limit:
            x, k = table[x], k + 1
        if x == b and (best is None or k < len(best)):
            best = [move] * k
    return best

def translate(rules, src, mode="plain"):
    # rules: list of (left glyphs, right glyphs) in reading order; the first rule whose left side matches is used
    out, i = [], 0
    while i < len(src):
        for L, R in rules:
            if src[i:i + len(L)] != L:
                continue
            out += R
            i += len(L)
            break
        else:
            return None
    return out

def tour(n, start, need):
    # fewest left/right presses to visit every box in need on a ring of n boxes, starting at start
    need = frozenset(need)
    seen = {(start, need - {start}): None}
    q = deque([(start, need - {start})])
    while q:
        p, left = q.popleft()
        if not left:
            path, s = [], (p, left)
            while seen[s] is not None:
                s, m = seen[s]
                path.append(m)
            return path[::-1]
        for m, d in (("4", 1), ("3", -1)):
            p2 = (p + d) % n
            s2 = (p2, left - {p2})
            if s2 not in seen:
                seen[s2] = ((p, left), m)
                q.append(s2)

learn(before[0], after["ans"]["glyphs"][0], "2")

def answer():
    return read_level(observe().board)

MEMO = {}   # plan / hypotheses for the next act(); sent with the first press

async def send(m):
    global MEMO
    memo, MEMO = MEMO, {}
    return await act([m], quiet=True, **memo)

async def fix(i, target):
    # press on box i until it shows target; learn every step
    while True:
        cur = answer()["ans"]["glyphs"][i]
        if cur == target:
            return None
        path = known_path(cur, target)
        m = path[0] if path else "2"
        r = await send(m)
        if r.level_up or r.state != "NOT_FINISHED":
            return r
        learn(cur, answer()["ans"]["glyphs"][i], m)

async def solve_answer(mode="plain", **memo):
    lv = answer()
    rules = [(a["glyphs"], b["glyphs"]) for a, b in lv["rules"]]
    want = translate(rules, lv["src"]["glyphs"], mode)
    have = lv["ans"]["glyphs"]
    if want is None or len(want) != len(have):
        print("NO TRANSLATION of the right length:", want and len(want), "for", len(have), "boxes")
        return None
    pos, n = lv["sel"][1], lv["ans"]["n"]
    need = [i for i in range(n) if have[i] != want[i]]
    path = tour(n, pos, need)
    print("boxes to change", need, "| cursor path", "".join(path))
    global MEMO
    MEMO = memo
    if pos in need:
        r = await fix(pos, want[pos])
        if r:
            return r
    for m in path:
        r = await send(m)
        if r.level_up or r.state != "NOT_FINISHED":
            return r
        pos = (pos + (1 if m == "4" else -1)) % n
        if answer()["sel"][1] != pos:
            print("DIFFERS: bracket at", answer()["sel"][1], "expected", pos)
            return r
        if pos in need:
            need.remove(pos)
            r = await fix(pos, want[pos])
            if r:
                return r
    print("all boxes match, but no level-up; answer row", [nm(g) for g in answer()["ans"]["glyphs"]])
    return None

r = await solve_answer(plan="Translate the sentence with the rules; walk the cursor round the boxes that differ and press each to its target.",
                       hypotheses=[{"text": "Up/down change the glyph in the box under the white bracket; left/right move the bracket.", "status": "verified", "evidence": [0]}])
print(r.lines[-1] if r and r.lines else r, "| cycle steps known:", len(NEXT))
