def shifted(glyphs, s):
    out = []
    for g in glyphs:
        for _ in range(abs(s)):
            g = (NEXT if s > 0 else PREV).get(g)
            if g is None:
                return None
        out.append(g)
    return out

def solve_rules(sides, src, ans, mode="plain"):
    # all shift choices (side -> presses, + is down) that make the shifted rules translate src into ans
    n = len(sides) // 2
    sols = []
    def ok(k, s, test):
        g = shifted(sides[k], s)
        return g is not None and test(g)
    def pick(k, a, f, test):      # shifts of side k that pass test
        if k in a:
            return [a[k]] if ok(k, a[k], test) else []
        return [s for s in SH if s not in f.get(k, ()) and ok(k, s, test)]
    def block(k, a, f, test):     # side k must fail test: forbid those shifts
        if k in a:
            return f if not ok(k, a[k], test) else None
        bad = {s for s in SH if ok(k, s, test)}
        if not bad:
            return f
        f = dict(f)
        f[k] = set(f.get(k, ())) | bad
        return None if len(f[k]) == 7 else f
    def lookup(test, a, f):       # the first rule whose left side passes test
        for q in range(n):
            for s in pick(2 * q, a, f, test):
                yield q, {**a, 2 * q: s}, f
            f = block(2 * q, a, f, test)
            if f is None:
                return
    def out_side(k, a, f, j):     # side k written into the answer from j
        L = len(sides[k])
        for s in pick(k, a, f, lambda g: g == ans[j:j + L]):
            yield {**a, k: s}, f, j + L
    def expand(q, a, f, j):
        if mode == "plain":
            yield from out_side(2 * q + 1, a, f, j)
            return
        k = 2 * q + 1
        for s in ([a[k]] if k in a else [s for s in SH if s not in f.get(k, ())]):
            R = shifted(sides[k], s)
            if R is None:
                continue
            a1 = {**a, k: s}
            if mode == "twice":
                for p, a2, f2 in lookup(lambda g: g == R, a1, f):
                    yield from out_side(2 * p + 1, a2, f2, j)
            else:
                def each(t, a2, f2, j2):
                    if t == len(R):
                        yield a2, f2, j2
                        return
                    for p, a3, f3 in lookup(lambda g: g[0] == R[t], a2, f2):
                        for a4, f4, j4 in out_side(2 * p + 1, a3, f3, j2):
                            yield from each(t + 1, a4, f4, j4)
                yield from each(0, a1, f, j)
    def match(i, j, a, f):
        if i == len(src):
            if j == len(ans):
                sols.append((a, f))
            return
        for q, a1, f1 in lookup(lambda g: g == src[i:i + len(g)], a, f):
            for a2, f2, j2 in expand(q, a1, f1, j):
                match(i + len(sides[2 * q]), j2, a2, f2)
    match(0, 0, {}, {})
    out = []
    for a, f in sols:
        full = dict(a)
        for k in range(len(sides)):
            if k not in full:
                full[k] = next(s for s in SH if s not in f.get(k, ()))
        out.append(full)
    return out

